  for (var i = 0; i < 3; i++) {}
  for (let j = 0; j < 3; j++) {}
  // Which of i and j can be read here? Apply the scope rules above.
}

// Example 2: a bare block
function tally() {
  {
    var x = 10;
    let y = 20;
