//   let/const are hoisted but uninitialized (temporal dead zone) until the declaration runs.
// - Redeclaring the same name: var allows it in the same scope; let throws SyntaxError.
// - Top-level var creates a property on the global object in scripts; let does not.

// General form:
// `text ${expression} more text`
// Backticks delimit the literal; ${...} holds any JS expression.
// The expression is evaluated, converted to a string, and inserted.

const city = "Oslo";
const n = 3;
