//   ${...} is just ordinary text there.
// - Template literals can span multiple lines;
//   newlines are kept in the string.
// - Escape a literal dollar-brace with a backslash: `\${x}`
// - Tagged templates: tag`a ${b}` call a function with
//   the string parts and values.
// - An unclosed ${ or missing backtick is a SyntaxError.

// General form:
//   `text ${expression} more text`
// The expression inside ${...} is evaluated, converted to a string,
// and spliced into the surrounding text.

const who = "Sam";
