query.syntax:
// General form: [...iterable] builds a NEW array from the
// elements of an iterable (array, string, Set, Map, ...)

const a = [1, 2, 3];
const b = [...a];          // new array, same element values
console.log(a === b);      // false (different array objects)

// Combining and inserting
const merged = [0, ...a, 4, ...'hi'];  // [0,1,2,3,4,'h','i']

// Elements are copied by value for primitives,
// but for objects/arrays the REFERENCE is copied.
const box = { label: 'x' };
const list = [box];
const list2 = [...list];
console.log(list2[0] === list[0]); // true: same object

// Gotchas:
// - Spread makes a SHALLOW copy: only the top level is new.
// - Nested objects/arrays are shared between original and copy,
//   so mutating one through either array is visible via the other.
// - Replacing an element (list2[0] = {...}) only affects list2.
// - For an independent deep copy use structuredClone(value)
//   (or copy nested levels manually).
// - Object spread {...obj} is also shallow.
// - Spreading a non-iterable into an array throws a TypeError.

// General form:
// const copy = { ...source1, ...source2, extraKey: value };
//
// Own enumerable properties of each source are copied in order,
// left to right, into the new object.
// When the same key appears more than once, the property is
// assigned each time it is encountered, so position matters.

const defaults = { color: 'red', size: 10 };
const custom = { size: 20, weight: 5 };

const x = { ...defaults, ...custom, id: 7 };
// keys: color, size, weight, id  (see order rule above to work out each value)

const y = { id: 1, ...defaults, id: 2 };
// explicit keys are also subject to the same left-to-right order

// Variations and gotchas:
// - Spread is shallow: nested objects are shared by reference.
// - null and undefined sources are ignored: { ...null } is {}.
// - Primitives: strings spread as indexed characters, numbers add nothing.
// - Only own enumerable properties are copied (no prototype props).
// - Getters are invoked and their values copied as plain data.
// - Symbol-keyed own enumerable properties are copied too.
// - Arrays spread into objects as index keys: { ...['a','b'] } -> {0:'a',1:'b'}.
// - Similar to Object.assign({}, a, b), but spread does not call setters on the target.

// General form:
// const [name = defaultExpr] = iterable;
// The default is used only when the matched value is
// strictly the value undefined (or the element is missing).

const [x = 10] = [5];        // existing value is used
const [y = 10] = [];         // missing element -> default applies

// Object destructuring follows the same rule:
const { p = 'dflt' } = { p: 'given' };

// Variations and gotchas:
// - The default is evaluated lazily, only when needed:
//   const [m = compute()] = [3];   // compute() is not called
// - Defaults can use earlier bindings:
//   const [s = 1, t = s + 1] = [];
// - Other falsy values (0, '', false, NaN) are real values,
//   so they are kept rather than replaced.
// - Compare with ?? and ||, which treat values differently:
//   value ?? fallback   // nullish check
//   value || fallback   // falsy check
// - Defaults also work in function parameters:
//   function f({ k = 2 } = {}) {}
// - Check precisely which values trigger the default:
//   only one specific value does, not every 'empty-looking' one.

// General form: positions in the pattern match positions in the iterable
// const [x, y, ...rest] = iterable;

// Example 1: a comma with no name leaves that position unbound
const [first, , third] = ['red', 'green', 'blue'];
// 'first' takes index 0; 'third' takes the index reached after counting the gap

// Example 2: several holes, and a trailing rest element
const [, , p, ...others] = [10, 20, 30, 40, 50];
// p comes from index 2; others collects whatever remains as an array

// Variations
// Default values:      const [m = 0, n = 5] = [7];       // used when value is undefined
// Swapping:            [m, n] = [n, m];                    // assignment form, no declaration
// Nested patterns:     const [[q], [, r]] = [[1], [2, 3]];
// Works on any iterable (Set, Map, string, generators), not only arrays

// Gotchas
// - Each comma advances exactly one position; an empty slot consumes one value.
// - Missing values give undefined (no error) unless the source is null/undefined,
//   which throws a TypeError.
// - The rest element must be last and cannot have a trailing comma.
// - Elisions are legal syntax in patterns, just like holes in array literals.

// General form:
// const [a, b, ...rest] = iterable;
//   a, b   -> take the first values by position
//   ...rest -> collects all remaining items into a NEW array

const [first, second, ...others] = ['a', 'b', 'c', 'd', 'e'];
// first and second are single values; others is an array of what is left

const [x, ...more] = ['only'];
// when nothing remains, the rest variable is an empty array (never undefined)

// Variations and gotchas:
// - The rest element must be last; no trailing comma allowed: [...r, ] is a SyntaxError
// - Only one rest element per pattern
// - Rest always produces an array, even from a string or Set:
//     const [c, ...cs] = 'xyz';   // cs is an array of characters
// - Skip positions with holes: const [, , ...r] = list;
// - Defaults apply to single items, not to rest: [a = 0, ...r]
// - Works in function parameters too: function f(a, ...args) {}
// - Object rest is similar: const { k, ...others } = obj;
// - Rest is a shallow copy; elements are not cloned

// General form:
// const { propertyName: newBinding } = object;
//   left of the colon  = the property to read from the object
//   right of the colon = the variable name that gets declared

const { title: heading } = { title: "Hello" };
// Which identifiers exist in scope afterwards? Only the ones
// on the right-hand side of each colon.

// Shorthand (no colon): property name and variable name are the same
const { size } = { size: 3 };

// Mixing renaming, shorthand, and defaults
const { x: px, y = 10, z: pz = 5 } = { x: 1 };
// px is 1, y is 10, pz is 5

// Nested patterns: the part after the colon can itself be a pattern
const { pos: { left } } = { pos: { left: 4 } };
// 'pos' is not bound here, only 'left'

// Computed keys need a rename target
const key = "k";
const { [key]: val } = { k: 7 };

// Gotchas:
// - Reading a missing property gives undefined (no error)
// - Destructuring null or undefined throws a TypeError
// - In an assignment (not a declaration) wrap in parentheses:
//   ({ a: target } = obj);

// General form
// const { prop = defaultValue } = object;
// The default is used only when the extracted value is strictly undefined
// (the property is missing, or explicitly holds undefined).

// Example 1: missing property
const { color = 'red' } = { size: 10 };

// Example 2: renaming plus a default
const { size: s = 5, weight: w = 0 } = { size: undefined, weight: 7 };

// Example 3: function parameter
function draw({ x = 0, y = 0 } = {}) {
  return [x, y];
}

// Gotchas
// - Only undefined triggers the default. Other falsy values
//   (0, '', false, NaN, and null) are kept as they are.
// - This differs from `||`, which replaces any falsy value,
//   and from `??`, which replaces null as well as undefined.
// - The default expression is evaluated lazily, only when needed.
// - Defaults can refer to earlier destructured names:
//   const { p = 1, q = p + 1 } = {};
// - Destructuring null or undefined itself throws a TypeError;
//   give the whole pattern a fallback: `= {}`.

// General form
// const { prop } = object;
// const { prop: newName } = object;
// const { prop = fallback } = object;
// const { prop: newName = fallback } = object;

// Example 1: reading and renaming
const user = { name: 'Ada', age: 36 };
const { name, age: years } = user;
// name -> 'Ada', years -> 36

// Example 2: default values
const { city = 'Unknown', name: n = 'Anon' } = { name: 'Bo' };
// A default is used only when the property value is undefined

// Variations and gotchas
// - Nested: const { p: { q } } = obj;  (throws if obj.p is null/undefined)
// - Rest: const { x, ...others } = obj;  collects remaining own enumerable props
// - Destructuring null or undefined throws a TypeError
// - Defaults do NOT apply to null, 0, '' or false
// - Without const/let, wrap in parentheses: ({ x } = obj);
// - In parameters: function f({ a = 1, b } = {}) { }
// - Properties are looked up by name, not by position (unlike arrays)

// General form
// const { prop } = expression;
// const { prop: alias = defaultValue } = expression;
// The right-hand side is converted to an object first (like ToObject),
// then properties are read from it.

// Example 1: primitives are wrapped, so this works
const { length } = "hello";   // reads String wrapper's length
const { toFixed } = 42;        // reads a method from Number.prototype

// Example 2: defaults apply only when the value is undefined
const { x = 10, y = 20 } = { x: undefined, y: null };
// x is 10 (undefined -> default), y is null (null is kept)

// Variations
// const { a, ...rest } = obj;        // collect remaining own enumerable props
// const { [key]: v } = obj;          // computed property name
// const { p: { q } } = obj;          // nested pattern
// function f({ id, name } = {}) {}   // parameter pattern with fallback
// ({ a, b } = obj);                  // assignment form needs parentheses

// Gotchas
// - Which values cannot be converted to an object? Check the spec's
//   RequireObjectCoercible / ToObject steps.
// - A nested pattern on a missing property fails the same way,
//   so give it a default: const { p: { q } = {} } = obj;
// - A default parameter (= {}) only covers undefined, not other values.

// General form: a bare identifier inside an object literal
// is expanded into a property whose key is the identifier's
// text and whose value is read from the variable of that name.
//
//   { identifier }   <->   { identifier: identifier }

const city = "Oslo";
const year = 2024;
const trip = { city, year };
// Mixed with normal properties:
const trip2 = { city, days: 5, year };

// Common variations
// - Works in function returns:
//     function make(id, tag) { return { id, tag }; }
// - Works with destructuring patterns (the reverse idea):
//     const { city: c, year } = trip;
// - Method shorthand is a separate feature:
//     const o = { greet() { return "hi"; } };
// - Computed keys have no shorthand form:
//     { [key]: value }

// Gotchas
// - The variable must be in scope, or a ReferenceError is thrown.
// - The value is captured when the literal is evaluated;
//   later reassignment of the variable does not change the property.
// - Only plain identifiers qualify; { a.b } is a SyntaxError.
// - Duplicate shorthand and explicit keys: the last one wins.

// General form:
// { [expression]: value }
// The expression inside the brackets is evaluated when the
// object literal is created. The result is converted to a
// property key (a string or a symbol).

const field = "color";
const item = { [field]: "red" };

// Any expression is allowed, not just a variable:
let n = 0;
const row = {
  ["col" + (n + 1)]: "a",
  [`col${n + 2}`]: "b",
};

// Works for methods, getters, setters, and symbols:
const sym = Symbol("tag");
const tool = {
  ["run" + "Now"]() { return 1; },
  get ["is" + "Ready"]() { return true; },
  [sym]: "s",
};

// Gotchas:
// - Non-symbol keys are converted with ToPropertyKey (string conversion).
// - Expressions are evaluated in source order, once per literal evaluation.
// - If two keys end up equal, the later one overwrites the earlier one.
// - Without brackets, the name is taken literally: { field: 1 } has key "field".
// - Shorthand { [x] } is not valid; a value or method body is required.
// - Brackets in a class body work too: class A { [name]() {} }

// General form:
// for (const|let|var binding of iterable) { body }
// binding is assigned each item produced by the iterable's iterator

const fruits = ["apple", "pear", "plum"];
for (const f of fruits) {
  console.log(f.toUpperCase());
}

// Works on any iterable: arrays, strings, Map, Set, NodeList,
// generators, arguments, typed arrays
for (const ch of "hey") { /* one character per step */ }

// Destructuring in the binding
for (const [k, v] of new Map([[1, "x"]])) { }
for (const [i, f] of fruits.entries()) { }

// Gotchas:
// - Plain objects are NOT iterable: for (x of {a:1}) throws TypeError
//   (use Object.keys / values / entries instead)
// - Contrast: for...in loops over enumerable property keys
//   (strings), not over the iterable's items
// - const is fine: each iteration creates a new binding
// - break / return / throw close the iterator early
// - Use `for await (const x of asyncIterable)` for async iterables

