query.syntax:
// General form
for (const key in expression) {
  // key is a string property name
}

// Example: a different shape of object
const base = { color: 'red' };
const item = Object.create(base);
item.size = 9;
for (const k in item) {
  console.log(typeof k); // keys are always strings
}

// Related tools
// Object.keys(o)     -> own enumerable string keys only
// Object.entries(o)  -> own enumerable [key, value] pairs
// Object.hasOwn(o, k) -> true if k is an own property
// for (const k in o) { if (!Object.hasOwn(o, k)) continue; ... }

// Gotchas
// - Walks the prototype chain: enumerable properties of prototypes are visited too.
// - Non-enumerable properties are skipped (e.g. built-in methods).
// - Symbol keys are never visited.
// - A property on the object shadows a same-named one on the prototype (visited once).
// - Order: integer-like keys ascending first, then string keys in creation order.
// - Avoid for...in on arrays: indexes are strings, and extra enumerable props appear.
// - for...of iterates values of iterables; for...in iterates keys.

// General form
// for (const name in object) { /* body */ }
//   - visits enumerable string-keyed properties of the object
//     AND those inherited through its prototype chain
//   - Symbol keys are skipped

// Example with a plain object
const car = { brand: "Volvo", year: 2020 };
for (const prop in car) {
  console.log(prop, car[prop]); // key name, then lookup of its value
}

// Example with an inherited property
const base = { shared: 1 };
const child = Object.create(base);
child.own = 2;
for (const k in child) {
  // visits "own" and also "shared" (inherited)
}

// Variations and gotchas
// - Property names are always strings (or symbols, which are skipped),
//   so think about what type the loop variable holds before doing math or
//   strict comparisons with it.
// - Order: integer-like keys ascending first, then other keys in
//   creation order.
// - Use Object.hasOwn(obj, k) to filter out inherited keys.
// - Prefer for...of to iterate VALUES of arrays, strings, Maps, Sets.
// - Object.keys(obj), Object.entries(obj) give own enumerable keys/pairs
//   as arrays, without walking the prototype chain.
// - Adding properties during the loop: they are not guaranteed to be
//   visited; deleted ones not yet visited are skipped.

// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: how different property values are handled
const s1 = JSON.stringify({ n: 5, f() {}, t: true, nul: null });
// Each value type has its own rule in objects.

// Example 2: arrays vs. objects
const s2 = JSON.stringify([function () {}, Symbol('x')]);
// Array slots must keep their positions, so they are treated differently
// from object properties.

// Gotchas / variations
// - Values with no JSON representation (undefined, functions, symbols)
//   are handled differently depending on whether they appear in an
//   object property, an array element, or at the top level.
// - null is a valid JSON value and is kept.
// - NaN, Infinity and -Infinity become null.
// - Symbol-keyed properties are ignored.
// - Only own enumerable string-keyed properties are included.
// - Date uses toJSON; any object with toJSON() is serialized from its result.
// - BigInt throws a TypeError unless you provide toJSON or a replacer.
// - Circular references throw a TypeError.
// - replacer (function or array of keys) can filter or transform values.
// - space (number or string) pretty-prints the output.

// General form
// JSON.stringify(value, replacer?, space?)  -> string (or undefined)

// JSON has no representation for some JS values, so stringify
// handles them differently depending on WHERE they appear.

// 1) As object property values: the property is omitted
JSON.stringify({ a: 1, b: function () {}, c: Symbol('s') });
// -> '{"a":1}'

// 2) As array elements: the slot must stay, so a placeholder is written
JSON.stringify([function () {}, Symbol('s')]);
// -> '[null,null]'

// 3) As the top-level value: the result is the value undefined (not a string)
JSON.stringify(function () {});
// -> undefined

// Gotchas (comments only):
// - Values skipped in objects / replaced in arrays: undefined, functions, symbols.
// - NaN, Infinity, -Infinity become null everywhere.
// - Sparse array holes are visited as undefined, so follow the array rule.
// - Date uses toJSON() and becomes an ISO string.
// - BigInt throws a TypeError.
// - A replacer function or toJSON() can change what gets serialized.

// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: which values survive inside an object
const o = { n: 5, s: "hi", t: true, nul: null, d: new Date(0) };
JSON.stringify(o);
// numbers, strings, booleans, null are kept; Date uses toJSON() -> ISO string

// Example 2: arrays vs objects
JSON.stringify([1, undefined, Symbol("x")]);
// In ARRAYS, unsupported values are converted to null (keeps positions)

// Example 3: replacer and indentation
JSON.stringify({ x: 1, y: 2 }, ["x"]);        // array replacer = allowed keys
JSON.stringify({ x: 1 }, null, 2);             // pretty print with 2 spaces
JSON.stringify({ x: 1, y: 2 }, (k, v) => typeof v === "number" ? v * 2 : v);

// Gotchas (comments)
// - Object properties whose values are undefined, functions, or symbols are
//   handled specially: they are not written as normal values.
// - Top-level undefined/function/symbol input returns undefined (not a string).
// - NaN and Infinity become null.
// - If an object has toJSON(), its return value is serialized instead.
// - Circular references throw TypeError; BigInt throws TypeError.
// - Only own enumerable string-keyed properties are included.
// - Map/Set serialize as {} unless converted first.

// General form
// JSON.parse(text)
// JSON.parse(text, reviver)   // reviver(key, value) can transform each value

// Examples
const list = JSON.parse('[1, "x", true, null]');   // text describing an array
const user = JSON.parse('{"name":"Ada","tags":["a"]}');
const dates = JSON.parse('{"d":"2020-01-01"}', (k, v) =>
  k === 'd' ? new Date(v) : v);

// JSON value kinds and what they become
// object -> object, array -> array, string -> string,
// number -> number, true/false -> boolean, null -> null

// Gotchas
// - The argument must be a string; other values are converted to a string first.
// - Invalid JSON throws SyntaxError (wrap in try/catch):
//   single quotes, unquoted keys, trailing commas, comments, undefined.
// - Strings inside JSON need double quotes, so in JS source the
//   outer literal usually uses single quotes or escapes.
// - Parsing a bare primitive text is valid: JSON.parse('42'), JSON.parse('"hi"').
// - Dates are not a JSON type; they stay as strings unless revived.
// - Duplicate keys: the last one wins.
// - JSON.stringify is the inverse (value -> text).

// General form:
//   new Constructor(...args)
// new calls the internal [[Construct]] method of the target.
// If the target has no [[Construct]], a TypeError is thrown
// ("... is not a constructor").

// Constructible: regular function declarations/expressions, classes
function Point(x, y) { this.x = x; this.y = y; }
const p = new Point(1, 2);

class Box { constructor(v) { this.v = v; } }
const b = new Box(5);

// Gotchas / variations:
// - Not every function has [[Construct]]. Examples that lack it:
//   methods in object literals/classes (shorthand), async functions,
//   generator functions, and many built-in non-constructor functions.
// - Functions without [[Construct]] also usually have no .prototype property.
// - Arrow functions bind `this` lexically, so they have no own `this`
//   for new to create; check by trying inside try/catch:
function isConstructor(f) {
  try { new (class extends f {}); return true; } catch { return false; }
}
// - new.target is undefined when a function is called without new,
//   and refers to the constructor when called with new.
// - Parentheses matter: new (expr)() evaluates expr first,
//   then constructs the result.
// - Class constructors throw if called without new.

// General form
// function name(...) { /* implicit local binding: arguments */ }
// (params) => expression   // arrow form

// Regular function: has its own array-like `arguments`
function total() {
  let sum = 0;
  for (let i = 0; i < arguments.length; i++) sum += arguments[i];
  return sum;
}

// Arrow function inside a regular function:
// name lookup for `arguments` continues to the enclosing function's scope
function outer() {
  const inner = () => arguments[0];
  return inner();
}

// Preferred modern alternative: rest parameters
const count = (...items) => items.length;

// Notes / gotchas
// - `arguments` is array-like: it has length and indexes, but no map/filter
//   (convert with Array.from(arguments) or [...arguments])
// - Arrow functions also take `this`, `super`, and `new.target`
//   from the surrounding scope, rather than defining their own
// - At top level of a module or in a global arrow, there may be no
//   enclosing function `arguments` to find (Node CommonJS wraps modules in a
//   function, so the lookup finds that wrapper's arguments instead)
// - A parameter or variable named `arguments` shadows the built-in object
// - Arrow functions cannot be used as constructors

// General idea:
// Before any code in a scope runs, the engine creates the bindings
// for that scope. What each kind of binding holds at that point differs.

// Example 1: using a name before its line in the source
console.log(typeof early);   // look at what exists before the line runs
var early = 5;

// Example 2: function expression assigned to a variable
// later();                  // depends on what the variable holds right now
// var later = function () { return 'x'; };

// Example 3: let / const and the temporal dead zone
// console.log(limit);       // accessing before the declaration line
// let limit = 10;           // throws ReferenceError in that window

// Variations and gotchas:
// - var: binding exists from scope start, value is undefined until assigned.
// - let / const / class: binding exists but is uninitialized (TDZ).
// - Function declarations: name and body are both set up at scope start.
// - Function expressions and arrow functions follow their variable's rules.
// - Hoisting is per scope: function scope for var, block scope for let/const.
// - Function declarations inside blocks have extra legacy rules in sloppy mode;
//   in strict mode they are block scoped.
// - If a var and a function declaration share a name, the function value
//   is in place first, then later assignments overwrite it.

// General form:
//   const name = initializer;   // binding exists from scope start, usable only after this line runs
//   let name = initializer;
//   var name = initializer;     // contrast: binding initialized to undefined at scope start
//   function name() {}          // contrast: declaration fully hoisted with its body

// Example 1: reading a lexical binding too early
// console.log(total);   // would throw ReferenceError (binding not yet initialized)
let total = 5;
console.log(total);      // 5

// Example 2: functions stored in variables follow the variable's rules
// greet();              // depends on how 'greet' was declared
const greet = () => 'hi';
greet();                 // fine: called after initialization

// Example 3: calls inside other functions are fine if they run later
function run() { return helper(); }
const helper = () => 'ok';
run();                   // works: helper is initialized by call time

// Gotchas:
// - The period from scope entry until the declaration line executes is the
//   temporal dead zone (TDZ) for let, const, and class.
// - Hoisting still happens for let/const: they shadow outer variables in the whole block.
// - typeof on a TDZ variable also throws.
// - var gives undefined before assignment; calling it then throws TypeError, not ReferenceError.
// - Function declarations can be called before their position in the source.
// - TDZ is based on execution order, not on where the text appears.

// General form
function name(param = defaultExpression) { /* ... */ }
const arrow = (param = defaultExpression) => { /* ... */ };

// Example
function greet(name = "guest", punct = "!") {
  return "Hi " + name + punct;
}

// Notes and gotchas (as comments):
// - The default expression is evaluated at call time, each call,
//   only when the default is actually needed.
// - Defaults can use earlier parameters:
//     function box(w, h = w) { return w * h; }
// - Defaults can call functions:
//     function stamp(t = Date.now()) { return t; }
// - A parameter with a default does not count toward fn.length
//   (length stops counting at the first parameter with a default).
// - Parameters with defaults may come before required ones, but
//   callers must then pass undefined explicitly to get the default.
// - Destructuring can have defaults too:
//     function cfg({ mode = "fast" } = {}) { return mode; }
// - Other falsy values (0, "", false, NaN) are ordinary values.
//   Compare with the || operator, which tests truthiness instead.
// - Think about which values count as "missing" for the parameter:
//   the rule is a strict check against one specific value.

