query.syntax:
// General form
// arr.sort()                 // default ordering
// arr.sort(compareFn)       // custom ordering
// compareFn(a, b) returns:
//   negative -> a goes before b
//   positive -> a goes after b
//   zero     -> keep relative order (sort is stable)

// Example 1: default ordering of mixed values
const words = ['pear', 'Apple', 'fig'];
words.sort();                // default compares elements as strings
                             // by UTF-16 code units (uppercase before lowercase)

// Example 2: custom comparator, descending by length
const items = ['aaa', 'b', 'cc'];
items.sort((x, y) => y.length - x.length);

// Gotchas
// - sort() mutates the original array and returns the same array.
//   Copy first to keep the original: [...arr].sort(fn)
//   or use arr.toSorted(fn) (returns a new array).
// - Without compareFn, non-undefined elements are converted to
//   strings and compared as text, whatever their type.
// - undefined elements are always placed at the end.
// - The comparator should return a number; returning a boolean
//   (x > y) is unreliable.
// - For locale-aware text: a.localeCompare(b)
// - Subtraction comparators can misbehave with NaN or Infinity.

// General form
//   a == b    loose equality: may convert operand types first
//   a === b   strict equality: no conversion; types must match
//   a != b / a !== b  are the negated forms

// Examples (different values from any quiz)
console.log(5 === 5);        // same type, same value
console.log(true === 1);     // different types: strict never converts

// Loose equality conversion rules (summary)
// - If both operands have the same type, == behaves like ===
// - null == undefined is true, and neither equals anything else loosely
// - number vs string: the string is converted to a number
// - boolean vs other: the boolean is converted to a number first
// - object vs primitive: the object is converted to a primitive
//   (via valueOf / toString) and then compared

// Gotchas
// - NaN is not equal to anything, even itself, under both operators
//   Use Number.isNaN(x) or Object.is(x, NaN)
// - +0 === -0 is true; Object.is(+0, -0) is false
// - Objects compare by reference: {} === {} is false
// - Loose comparisons are not transitive, so results can surprise
// - Prefer === unless you deliberately want conversion
//   (x == null is a common idiom to test null or undefined)

