// General forms
//   array.includes(value)   -> boolean, linear search
//   set.has(value)          -> boolean, hash-based lookup
//   new Set(iterable)       -> collection of unique values

// Example: checking tags against a list
const tagList = ['a', 'b', 'c', 'd'];
tagList.includes('c');      // walks elements one by one

const tagSet = new Set(tagList);
tagSet.has('c');            // looks the value up by hash

// Cost model (n = number of items in the collection)
// - Array includes/indexOf: time grows roughly with n per call (O(n))
// - Set has: roughly constant time on average per call (O(1))
// - Building a Set costs O(n) once; it pays off when you do many lookups
// - Few lookups or tiny collections: the difference is negligible

// Gotchas
// - Both use SameValueZero, so NaN is found; +0 and -0 are equal
// - Objects compare by reference, not by contents
// - Set keeps unique values in insertion order
// - Total work for m lookups: array ~ m * n, set ~ n + m
// - Where in the array a value sits matters: early items are found sooner,
//   missing values scan the whole array

// Array.prototype.map(callback(element, index, array))
//   -> new array, same length, one callback result per element
const names = ['ann', 'bo', 'cy'];
const upper = names.map((s) => s.toUpperCase());

// Array.prototype.reduce(callback(acc, element, index, array), initialValue)
//   -> single accumulated value; acc is whatever the callback returned last time
const total = [1, 2, 3].reduce((sum, n) => sum + n, 0);

// Spread creates a NEW array by copying every element of the source:
const a = [1, 2, 3];
const b = [...a, 4];   // copies a (3 elements), then adds 4
// Cost of one copy grows with the array's length: O(n).
// Doing a copy inside a loop/callback repeats that cost on every iteration,
// so total work is the sum of the copy sizes (1 + 2 + ... + n).

// Mutating alternatives avoid the repeated copy:
//   acc.push(x); return acc;       // amortized O(1) per step
//   for (const x of src) out.push(x);

// Gotchas:
// - Count work per iteration, not just the number of iterations.
// - reduce without initialValue uses the first element as acc and
//   throws on an empty array.
// - Big-O describes growth; for tiny inputs differences are negligible.
// - Object spread ({...obj}) in a reduce has the same copy-per-step cost.
